import VendorCard from '../../components/vendor/VendorCard';
import EarningsChart from '../../components/vendor/EarningsChart';
import { useDashboardQuery } from '../../store/api/vendorApi';
export default function VendorDashboard(){const{data,isLoading}=useDashboardQuery();const s=data?.stats||{};return <main className="mx-auto max-w-7xl px-4 py-10"><h1 className="font-heading text-5xl text-navy">Vendor Dashboard</h1>{isLoading&&<p>Loading dashboard...</p>}<div className="mt-6 grid gap-4 md:grid-cols-4"><VendorCard title="Sales" value={`₹${s.sales||0}`} caption="Last 30 days"/><VendorCard title="Orders" value={s.orders||0} caption="Recent demand"/><VendorCard title="Products" value={s.products||0} caption="Live catalog"/><VendorCard title="Rating" value={s.rating||0} caption="Customer trust"/></div><div className="card mt-6 p-5"><h2 className="font-heading text-3xl text-navy">Revenue</h2><EarningsChart /></div><div className="mt-6 grid gap-4 lg:grid-cols-2"><div className="card p-5"><h2 className="font-bold text-navy">Recent Orders</h2>{data?.recentOrders?.map(o=><p className="mt-2" key={o._id}>{o.orderNumber} - {o.orderStatus}</p>)}</div><div className="card p-5"><h2 className="font-bold text-navy">Low Stock Alerts</h2>{data?.lowStock?.map(p=><p className="mt-2" key={p._id}>{p.name}: {p.stock}</p>)}</div></div></main>}
